from pathlib import Path
import json
p=Path(__file__).resolve().parents[1]/'data/buildings.json'; data=json.loads(p.read_text()); by={x['slug']:x for x in data}
rows={
'khram-artemidy':([('https://zombie-island.moy.su/blog/khram_artemidy_postrojka_zombie_farm_mania/2013-07-19-2124','Zombie-island: Храм Артемиды'),('https://www.fatalgame.com/answer/zombiferma/построить-храм-артемиды-в-игре-зомби-ферма','Fatalgame, 06.04.2015: стадии и квест'),('https://zombie-island.moy.su/blog/prognoz_zadaniya_prokhozhdenie_kvesty_igry_zombie_farm_mania/2013-07-19-2129','Zombie-island: квест Прогноз'),('https://zombie-island.moy.su/blog/bashnja_zadaniya_prokhozhdenie_kvesty_igry_zombie_farm_mania/2013-07-19-2128','Zombie-island: квест Башня')],{'Стоимость и стадии':'Статья указывает 1-й уровень, покупку за 200 000 монет, продажу за 20 000, 300 опыта за покупку и 750 всего. Стадия 1: 50 блоков, 15 песка, 15 воды — 150 опыта. Стадия 2: 50 времени, 10 песка, 10 колоннад — 300 опыта. Fatalgame приводит те же стадии.','Назначение':'Создание соломенных, деревянных и каменных декораций. Под постройкой у друзей в том числе указаны металлолом, бесплатные лопаты, опыт и монеты.','Квесты и неопределённость':'Статья о постройке связывает покупку с квестом «Торг», а строительство — то с «Башней», то с «Прогнозом». Отдельная статья квеста «Прогноз» прямо требует достроить храм; «Башня» — предыдущий квест. Точный момент разблокировки постройки этим не доказан.'}),
'shattl-tic-tac':([('https://zombie-island.moy.su/blog/shattl_tic_tac_postroyka_zombie_farm_zombi_manija/2013-02-23-1782','Zombie-island: Шаттл Tic Tac'),('https://zombie-island.moy.su/blog/svezhesti_navstrechu_zadaniya_prokhozhdenie_kvesty_igry_zombie_farm_mania/2013-02-23-1779','Zombie-island: получение в квесте')],{'Акция и происхождение':'По статье, рекламная постройка появилась 23 февраля 2013 года. Фундамент получали в задании «Свежести навстречу» после вступления в группу и нажатия кнопки получения; находился на складе и ставился на Домашнем острове. Исторически не покупался и не продавался.','Стадии':'1: 15 металла, 10 зелёной краски, 15 шестерён — 100 опыта; 2: 15 цемента, 5 белой краски, 3 флюгера — 200 опыта; 3: 1 микросхема, 3 лампочки, 1 нефть — 300 опыта.','Исторические правила':'В квестовой фазе Свет создавался из 1 металла и 1 трансформатора, а шаттл превращался в подарок. В другом фрагменте статья описывает позднее поведение: рулетку раз в 24 часа с Любовью или Светом, при выпадении Света — превращение в коробку. Дата смены правил и применимость ко всем платформам не установлены.'}),
'kupol-za-golosa':([('https://zombie-island.moy.su/blog/kupol_za_golosa_postroyka_zombie_farm_mania/2013-06-29-2034','Zombie-island: Купол за голоса и превращения')],{'Стоимость и стадии':'Источник указывает 1-й уровень, 35 голосов, 650 опыта за покупку и 1900 всего. Стадия 1: 80 блоков, 50 кувалд, 5 бигуди; 2: 120 досок, 100 красной черепицы, 30 фанеры; 3: 100 синей черепицы, 10 бигуди, 100 гвоздей; 4: 120 цемента, 100 воды, 50 листов золота; 5: 1 капитан, 80 кирпичей, 15 бигуди. Во второй стадии подпись ссылки ошибочно говорит «Гвозди», но текст и рисунок указывают фанеру.','Превращение островов':'Исторически позволял превращать некоторые старые острова в новые; источник предупреждает, что оставшиеся постройки, ресурсы и декорации при превращении исчезнут. Примеры: Остров Надежды — 33 Мир и 5 золотых рыбок; Новые пещеры Зу — 45 угля и 15 Z-кнопок. Статья могла обновляться; не переносить рецепты на вариант за зомбаксы без проверки.'})}
for slug,(sources,fields) in rows.items():
 x=by[slug]; rid='temple-shuttle-dome-verified-'+slug
 for url,label in sources:
  if not any(s['url']==url for s in x['sources']):x['sources'].append({'url':url,'label':label})
 if not any(z.get('original_id')==rid for z in x['prior_records']):x['prior_records'].append({'original_id':rid,'original_category':'Исторические статьи и квесты','version':'браузерная версия; платформы и редакции могут различаться','date':'даты статей в адресах; дата последней редакции неизвестна','fields':fields,'confidence':'Фанатские источники; совпадение сведений не гарантирует независимость. Условия в разные периоды могли изменяться.'})
p.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
